<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Credential Files · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'credential-documents',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">SECURE COMPLIANCE FILES</p><h1>Credential documents</h1><p>Attach source documents to credential records without exposing private storage publicly.</p></div><a class="button secondary" href="<?=esc(url_for('workforce-experience'))?>">Workforce experience</a></header><?php if($notice):?><div class="page-flash success"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><section class="planning-grid"><article class="panel"><h2>Upload document</h2><form method="post" enctype="multipart/form-data" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="upload_credential_document"><label>Credential<select name="member_credential_id"><?php foreach($credentials as $credential):?><option value="<?=$credential['id']?>"><?=esc($credential['staff_name'].' · '.$credential['credential_name'])?></option><?php endforeach;?></select></label><label>PDF, JPG, or PNG<input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" required></label><button class="button primary">Upload securely</button></form></article><article class="panel"><h2>Stored files</h2><?php foreach($credentialDocuments as $document):?><div class="planning-row"><span><strong><?=esc($document['staff_name'].' · '.$document['credential_name'])?></strong><small><?=esc($document['original_name'].' · '.round($document['file_size']/1024).' KB')?></small></span><a class="button secondary" href="<?=esc(url_for('credential-document?id='.$document['id']))?>">Download</a></div><?php endforeach;?><?php if(!$credentialDocuments):?><div class="inline-empty"><strong>No credential files uploaded</strong></div><?php endif;?></article></section></main></body></html>
